def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration string")

    total_seconds = 0
    current_num = ""

    units = {'h': 3600, 'm': 60, 's': 1}
    seen_units = set()

    for char in s:
        if char.isdigit():
            current_num += char
        elif char in units:
            if not current_num:
                raise ValueError("Invalid duration string")
            if char in seen_units:
                raise ValueError("Invalid duration string")
            total_seconds += int(current_num) * units[char]
            seen_units.add(char)
            current_num = ""
        else:
            raise ValueError("Invalid duration string")

    if current_num:
        raise ValueError("Invalid duration string")

    return total_seconds
```

